$q = sprintf("UPDATE webfinance\_personne SET nom='%s',prenom='%s',email='%s',tel='%s',mobile='%s',fonction='%s',note='%s' WHERE id\_personne=%d", mysql\_real\_escape\_string($_POST['nom']), mysql\_real\_escape\_string($_POST['prenom']), mysql\_real\_escape\_string($_POST['email']), mysql\_real\_escape\_string(removeSpace($_POST['tel'])), mysql\_real\_escape\_string(removeSpace($_POST['mobile'])), mysql\_real\_escape\_string($_POST['fonction']), mysql\_real\_escape\_string($_POST['note']), mysql\_real\_escape\_string($_POST['id\_personne']));
